"""Shared conversions for Meridian CRM legacy storage conventions."""

from __future__ import annotations

from datetime import date
from decimal import Decimal, ROUND_HALF_UP
import re

_LEGACY_NULL_DATE = "00000000"
_LEGACY_DATE_RE = re.compile(r"^\d{8}$")
_ISO_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO YYYY-MM-DD, preserving null semantics."""
    if yyyymmdd in (None, "", _LEGACY_NULL_DATE):
        return None

    if not isinstance(yyyymmdd, str) or not _LEGACY_DATE_RE.fullmatch(yyyymmdd):
        raise ValueError("legacy date must be in YYYYMMDD format")

    try:
        return date(
            int(yyyymmdd[:4]),
            int(yyyymmdd[4:6]),
            int(yyyymmdd[6:8]),
        ).isoformat()
    except ValueError as exc:
        raise ValueError("legacy date must be a valid calendar date") from exc


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to the legacy YYYYMMDD representation."""
    if iso in (None, ""):
        return _LEGACY_NULL_DATE

    if not isinstance(iso, str) or not _ISO_DATE_RE.fullmatch(iso):
        raise ValueError("ISO date must be in YYYY-MM-DD format")

    try:
        return date.fromisoformat(iso).strftime("%Y%m%d")
    except ValueError as exc:
        raise ValueError("ISO date must be a valid calendar date") from exc


def yn(char: str | None) -> bool:
    """Convert the legacy Y/N flag convention to a boolean."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal currency amount to integer minor units.

    JPY has zero minor-unit digits; all other currencies use two.  Conversion
    uses Decimal and legacy half-up rounding.
    """
    if amount is None or amount == "":
        return 0

    if currency is None or currency.strip() == "":
        currency = "USD"

    exponent = 0 if currency.strip().upper() == "JPY" else 2
    scale = Decimal(10) ** exponent
    decimal_amount = Decimal(str(amount))
    return int((decimal_amount * scale).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
